<?php
if(!defined('ABSPATH'))exit;
class InfoContainer_OpenAI_Settings{
const OPTION='infocontainer_openai_secret'; const CIPHER='aes-256-gcm';
public function register(){add_management_page('Configuración de InfoContainer','Configuración de InfoContainer','manage_options','infocontainer-settings',[$this,'render']);}
public function render(){if(!current_user_can('manage_options'))wp_die('No autorizado.','',['response'=>403]);$external=defined('INFOCONTAINER_OPENAI_API_KEY')||false!==getenv('INFOCONTAINER_OPENAI_API_KEY');echo '<div class="wrap"><h1>Configuración de InfoContainer</h1><h2>Integración con OpenAI</h2><p>Estado: <strong>'.(self::has_stored()?'Clave configurada':'Clave no configurada').'</strong></p>';if($external)echo '<p><strong>Hay una configuración externa con prioridad.</strong> La clave guardada aquí no es la activa.</p>';if(isset($_GET['infocontainer_settings_message']))echo '<div class="notice notice-info"><p>'.esc_html(sanitize_text_field(wp_unslash($_GET['infocontainer_settings_message']))).'</p></div>';echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="infocontainer_save_openai"><input type="password" name="infocontainer_openai_key" value="" autocomplete="new-password" class="regular-text"><p class="description">El campo se deja vacío al volver. Vacío no borra la clave.</p>';wp_nonce_field('infocontainer_save_openai','infocontainer_openai_nonce');submit_button('Guardar configuración');echo '</form>';if(self::has_stored()){echo '<hr><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="infocontainer_delete_openai">';wp_nonce_field('infocontainer_delete_openai','infocontainer_delete_nonce');submit_button('Eliminar clave guardada', 'delete', 'submit', true);echo '</form>';}echo '</div>';}
public function save(){if(!current_user_can('manage_options')||!check_admin_referer('infocontainer_save_openai','infocontainer_openai_nonce'))wp_die('Solicitud no autorizada.','',['response'=>403]);$key=isset($_POST['infocontainer_openai_key'])?trim((string)wp_unslash($_POST['infocontainer_openai_key'])):'';if(''===$key)$this->message('Sin cambios: el campo vacío conserva la configuración.');$enc=self::encrypt($key);if(is_wp_error($enc))$this->message('No se pudo guardar de forma segura.');update_option(self::OPTION,$enc,false);$this->message('Configuración guardada sin mostrar la clave.');}
public function delete(){if(!current_user_can('manage_options')||!check_admin_referer('infocontainer_delete_openai','infocontainer_delete_nonce'))wp_die('Solicitud no autorizada.','',['response'=>403]);delete_option(self::OPTION);$this->message('Clave guardada eliminada.');}
private function message($m){wp_safe_redirect(add_query_arg(['page'=>'infocontainer-settings','infocontainer_settings_message'=>$m],admin_url('tools.php')));exit;}
public static function has_stored(){return is_array(get_option(self::OPTION,null))&&false!==self::decrypt(get_option(self::OPTION,null));}
public static function stored_key(){ $v=get_option(self::OPTION,null);$x=self::decrypt($v);return is_string($x)?$x:''; }
private static function material(){foreach(['AUTH_KEY','SECURE_AUTH_KEY','LOGGED_IN_KEY','NONCE_KEY'] as $n)if(!defined($n)||!is_string(constant($n))||strlen(constant($n))<16)return false;return hash('sha256','InfoContainer OpenAI key v1|'.AUTH_KEY.'|'.SECURE_AUTH_KEY.'|'.LOGGED_IN_KEY.'|'.NONCE_KEY,true);}
private static function encrypt($plain){$k=self::material();if(false===$k||!function_exists('openssl_encrypt'))return new WP_Error('crypto_unavailable');$iv=random_bytes(12);$tag='';$c=openssl_encrypt($plain,self::CIPHER,$k,OPENSSL_RAW_DATA,$iv,$tag,'infocontainer');return is_string($c)?['v'=>1,'iv'=>base64_encode($iv),'tag'=>base64_encode($tag),'ciphertext'=>base64_encode($c)]:new WP_Error('crypto_failed');}
private static function decrypt($v){$k=self::material();if(false===$k||!is_array($v)||empty($v['iv'])||empty($v['tag'])||empty($v['ciphertext']))return false;$iv=base64_decode($v['iv'],true);$tag=base64_decode($v['tag'],true);$c=base64_decode($v['ciphertext'],true);if(false===$iv||false===$tag||false===$c)return false;$p=openssl_decrypt($c,self::CIPHER,$k,OPENSSL_RAW_DATA,$iv,$tag,'infocontainer');return is_string($p)?$p:false;}
}
